 V('rhetorical flourish=floreio retórico|rule of three=regra dos três|rallying cry=grito de mobilização|stump speech=discurso de campanha|applause line=frase feita para aplausos|soundbite=trecho citável|keynote address=discurso de abertura|podium presence=presença ao microfone|cold-open sentence=frase de abertura seca|closing peroration=peroração final|interrogative flourish=floreio interrogativo|paired contrast=contraste em par|rhythmic cadence=cadência rítmica|held silence=silêncio sustentado|rising tricolon=tricolon crescente|balanced clauses=orações equilibradas|oratory tutor=tutor de oratória|lectern jitters=tremedeira diante do púlpito|lectern notes=anotações do púlpito|teleprompter script=roteiro de teleprompter|crowd reaction=reação da plateia|closing summons=convocação final|memorable closer=fecho memorável|pathos-laden plea=apelo carregado de pathos|attention-grabbing lead=abertura que prende a atenção|vocal delivery=entrega vocal|pace of delivery=ritmo da fala|speech skeleton=esqueleto do discurso|crowd chemistry=sintonia com a multidão|rhetorical register=registro retórico'),
 ('Rehearsal room',[('Coach','Open with three short phrases, then repeat your first words.','Abra com três frases curtas e depois repita suas primeiras palavras.'),('Speaker','We will not retreat. We will not relent.','Não recuaremos. Não cederemos.'),('Coach','Better. Now pause before the last line.','Melhor. Agora faça uma pausa antes da última frase.'),('Speaker','We will not forget. Did that land?','Não esqueceremos. Isso funcionou?')]),
