Q('C2-L103','Integrated communication: Public discourse — the speechwriter',
 'eu consigo ler, ouvir, falar e escrever sobre o ofício de redigir discursos a partir de uma entrevista, usando a expressão The tip of the iceberg com entonação precisa.',
 ('Reading · An interview',iv('A veteran speechwriter explains what the audience never sees.',[('Interviewer: What does a good speech require?','Months of listening. The finished text is **the tip of the iceberg**: beneath it lie interviews, drafts, and arguments about a single adjective.'),('Interviewer: How do you find the speaker’s voice?','I **shadow** them. I note how they joke, where they hesitate, what they **refuse** to say. A speech must sound **like the person**, only **sharper**.'),('Interviewer: Do you ever write what you disagree with?','Often. A ghostwriter **lends** words, not convictions. But I **draw the line** at claims I know are false.')],gloss=[('shadow','acompanhar de perto'),('hesitate','hesitar'),('ghostwriter','redator fantasma'),('convictions','convicções')])),
 [('The audience sees most of the speechwriter’s work.','F','the tip of the iceberg.'),('The writer studies the speaker’s habits.','T','I shadow them.'),('She writes false claims if asked.','F','draw the line at claims I know are false.')],
 [('“the tip of the iceberg” = ?',['apenas a parte visível de um problema maior','um iceberg pequeno','um erro grave'],0,'the tip of the iceberg.'),('“ghostwriter” = ?',['quem escreve sem assinar','escritor de terror','revisor'],0,'ghostwriter.')],
 G('Expressões de proporção e de bastidores',['Expressão','Exemplo','Sentido'],[['**the tip of the iceberg**','The text is **the tip of the iceberg**.','só a parte visível'],['**behind the scenes**','Months of work happen **behind the scenes**.','nos bastidores'],['**not so much… as…**','It is **not so much** eloquence **as** listening.','ênfase comparativa'],['**more often than not**','**More often than not**, the best line is cut.','na maioria das vezes']],'**The tip of the iceberg** pressupõe um **resto oculto maior**. Use-a para dizer que o que se vê é uma fração do problema ou do trabalho.',warn='Não use a expressão para algo pequeno e *completo*: ela implica algo maior escondido.'),
 [('The finished text is the ___ of the iceberg. (tip)','tip','expressão.',None),('I ___ the speaker for weeks. (shadow)','shadow','verbo.',None),('A ghostwriter ___ words, not convictions. (lend)','lends','verbo.',None),('I ___ the line at claims I know are false. (draw)','draw','expressão.',None)],
 V('speechwriting office=gabinete de redação de discursos|ghostwritten text=texto escrito por terceiro|authentic cadence=cadência autêntica|verbal tic=cacoete verbal|rewrite round=rodada de reescrita|client approval=aprovação do cliente|factual vetting=checagem de fatos|electioneering circuit=circuito eleitoral|issue memo=memorando temático|joke pass=revisão de piadas|delivery cue=indicação de entrega|line edit=revisão linha a linha|applause cue=deixa de aplauso|authorial credit=crédito autoral|private conviction=convicção íntima|pet phrase=frase favorita|felicitous wording=formulação feliz|cutting-room floor=sobras da edição|adjective dispute=disputa por um adjetivo|tonal register=registro tonal|bland platitude=lugar-comum insosso|political ghost=sombra política|talking points=pontos de fala|first sentence rule=regra da primeira frase|memorable phrase=frase memorável|press-ready text=texto pronto para a imprensa|speech archive=arquivo de discursos|speaker prompt=roteiro do orador|oral rhythm=ritmo oral|final polish=último polimento'),
 ('Behind the scenes',[('Reporter','So the speech is the tip of the iceberg?','Então o discurso é só a ponta do iceberg?'),('Writer','Yes. Weeks of interviews sit beneath it.','Sim. Semanas de entrevistas estão por baixo.'),('Reporter','Do you ever refuse a line?','Você já recusou uma frase?'),('Writer','I draw the line at anything I know is untrue.','Eu traço o limite em qualquer coisa que sei ser falsa.')]),
 [('Use the tip of the iceberg.','Use.','The leaked memo is the tip of the iceberg.'),('Contrast two ideas with not so much… as…','Use.','It is not so much talent as discipline.'),('Say where you draw the line.','Diga.','I draw the line at inventing quotations.')],
 ('Write a 5-sentence profile of a speechwriter, using the tip of the iceberg and not so much… as….','Her speeches look effortless, but they are the tip of the iceberg. Behind the scenes lie weeks of interviews and rewrites. Her gift is not so much eloquence as attention. She shadows every client before she writes a word. More often than not, her best line is the one she cuts.',['Usei **the tip of the iceberg**','Usei **not so much… as**'],'5 frases'),
 verbs=[('ghostwrite','escrever em nome de outra pessoa','Aides ghostwrite many speeches.','Assessores escrevem muitos discursos em nome do político.')],
 expr=[('The tip of the iceberg','a ponta do iceberg'),('Behind the scenes','nos bastidores'),('Draw the line','traçar um limite'),('Read between the lines','ler nas entrelinhas'),('Put words in someone’s mouth','pôr palavras na boca de alguém'),('Chapter and verse','com todos os detalhes'),('Weigh one’s words','medir as palavras'),('Choose one’s words carefully','escolher as palavras com cuidado'),('Have a way with words','ter jeito com as palavras'),('In so many words','com todas as letras'),('Mince words','usar rodeios')],pron=AJ)
